arguments.new_str:
using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: Default discriminator property renamed from
        // "Discriminator" to "$type" in EF Core 9. Preserve the old name
        // so existing documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: Default id format changed from "EntityType|Key"
        // to just the raw key in EF Core 9. Preserve the old format so
        // existing documents (e.g. "Blog|1") are still addressable.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id")
            .ToJsonProperty("id");

        // Breaking change 3: HasIndex() now throws for Cosmos provider.
        // Cosmos manages indexing via its own indexing policy, not EF indexes.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);

        // Breaking change 4: Sync I/O over async now throws by default.
        // If sync calls are still needed, opt back in explicitly.
        // Prefer migrating to async (see SyncJob.cs).
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

arguments.old_str:
class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();
    }
}

arguments.new_str:
using Microsoft.EntityFrameworkCore;
class SyncJob
{
    // Breaking change 4: Cosmos provider no longer allows sync I/O by default.
    // Migrated to async to avoid InvalidOperationException at runtime.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }
}

