        // existing documents that store Id separately still work.
        modelBuilder.Entity<Blog>().HasShadowId();

        // Breaking change 4 (Low): HasIndex() now throws for Cosmos.
        // Cosmos manages indexing via its own indexing policy.
        // Removed: modelBuilder.Entity<Blog>().HasIndex(b => b.Name);
    }
}
